/**
 * Cinejoy webOS - Deterministic 2D Spatial Remote Navigation & Focus Memory Engine
 * Standard: 10-Foot Television UX, webOS 8.5.0 (Chromium ~108+)
 * Target Device: LG 32LR686BPSA (1920x1080 Full HD Canvas)
 * 
 * Features:
 * - 2D Directional Spatial Navigation (edge-to-edge primary, orthogonal penalty, overlap bonus)
 * - Adaptive Two-Pass Directional Cones (60 deg strict, 85 deg fallback)
 * - webOS Remote Keycodes (38, 40, 37, 39, 13, 461/27, Media, Color keys)
 * - Key Repeat Throttling (60ms threshold, rapid burst detection)
 * - TV-Safe Two-Tier Auto-Scrolling (96px horizontal, 54px vertical, 104px header clearance)
 * - Stateful Per-View Focus Memory (6-step resolution cascade)
 * - Modal & Virtual Keyboard Focus Trapping (trap / untrap)
 */

(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.SpatialNav = factory();
  }
})(typeof window !== 'undefined' ? window : this, function () {
  'use strict';

  // ---------------------------------------------------------------------------
  // 1. Constants & Configuration
  // ---------------------------------------------------------------------------
  var CONSTANTS = Object.freeze({
    SAFE_X_MIN: 96,
    SAFE_X_MAX: 1824, // 1920 - 96
    SAFE_Y_MIN: 54,
    SAFE_Y_MAX: 1026, // 1080 - 54
    HEADER_HEIGHT: 84,
    EFFECTIVE_Y_MIN: 104, // 84 + 20px buffer
    PEEK_OFFSET: 48,
    THROTTLE_INTERVAL: 60
  });

  var KEY_CODES = Object.freeze({
    UP: [38],
    DOWN: [40],
    LEFT: [37],
    RIGHT: [39],
    ENTER: [13],
    BACK: [461, 27],
    BACKSPACE: [8],
    PLAY: [415, 179],
    PAUSE: [19],
    PLAY_PAUSE: [179],
    STOP: [413, 178],
    FAST_FORWARD: [417, 228],
    REWIND: [412, 227],
    COLOR_RED: [403],
    COLOR_GREEN: [404],
    COLOR_YELLOW: [405],
    COLOR_BLUE: [406]
  });

  var CONFIG = {
    activeClass: 'focused',
    tvFocusedClass: 'tv-focused',
    navigableSelector: '[data-nav="true"]',
    activeViewSelector: '.view.active',
    headerSelector: '.app-header',
    headerHiddenClass: 'header-hidden',
    orthogonalWeight: 2.5,
    overlapWeight: 1.5,
    maxOverlapBonus: 120,
    strictConeAngle: 60,   // degrees
    fallbackConeAngle: 85, // degrees
    epsilon: 4             // px tolerance
  };

  // ---------------------------------------------------------------------------
  // 2. Internal Engine State
  // ---------------------------------------------------------------------------
  var state = {
    initialized: false,
    enabled: true,
    currentFocus: null,
    previousFocus: null,
    activeTrap: null,
    viewMemory: {},
    listeners: {},
    lastMoveTimestamp: 0,
    rapidCount: 0,
    _keydownHandler: null
  };

  // ---------------------------------------------------------------------------
  // 3. Helper Functions
  // ---------------------------------------------------------------------------

  function normalizeDirection(dir) {
    if (!dir) return null;
    var d = String(dir).toLowerCase();
    if (d === 'arrowup' || d === 'up') return 'up';
    if (d === 'arrowdown' || d === 'down') return 'down';
    if (d === 'arrowleft' || d === 'left') return 'left';
    if (d === 'arrowright' || d === 'right') return 'right';
    return null;
  }

  function emit(eventName, payload) {
    var handlers = state.listeners[eventName];
    if (handlers && handlers.length) {
      for (var i = 0; i < handlers.length; i++) {
        try {
          handlers[i](payload);
        } catch (err) {
          console.error('[SpatialNav] Event error in ' + eventName + ':', err);
        }
      }
    }
  }

  function getCurrentViewName() {
    if (typeof document === 'undefined') return 'home';
    var activeView = document.querySelector(CONFIG.activeViewSelector);
    if (activeView && activeView.id) {
      return activeView.id.replace('view-', '');
    }
    return 'home';
  }

  function resolveKeyAction(e) {
    if (!e) return null;
    var code = e.keyCode || e.which;
    var key = e.key || '';

    // D-Pad Navigation
    if (code === 38 || key === 'ArrowUp' || key === 'Up') return 'MOVE_UP';
    if (code === 40 || key === 'ArrowDown' || key === 'Down') return 'MOVE_DOWN';
    if (code === 37 || key === 'ArrowLeft' || key === 'Left') return 'MOVE_LEFT';
    if (code === 39 || key === 'ArrowRight' || key === 'Right') return 'MOVE_RIGHT';

    // Select / Enter
    if (code === 13 || key === 'Enter') return 'SELECT';

    // Back Navigation
    if (code === 461 || code === 27 || key === 'Escape' || key === 'Back' || key === 'XF86Back') {
      return 'BACK';
    }
    if (code === 8 || key === 'Backspace') return 'BACKSPACE';

    // Media Playback
    if (code === 415 || (code === 179 && key === 'MediaPlay') || key === 'Play') return 'MEDIA_PLAY';
    if (code === 19 || key === 'MediaPause' || key === 'Pause') return 'MEDIA_PAUSE';
    if (code === 179 || key === 'MediaPlayPause') return 'MEDIA_PLAY_PAUSE';
    if (code === 413 || code === 178 || key === 'MediaStop' || key === 'Stop') return 'MEDIA_STOP';
    if (code === 417 || code === 228 || key === 'MediaFastForward' || key === 'FastForward') return 'MEDIA_FAST_FORWARD';
    if (code === 412 || code === 227 || key === 'MediaRewind' || key === 'Rewind') return 'MEDIA_REWIND';

    // webOS Dedicated Color Keys
    if (code === 403 || key === 'ColorF0Red' || key === 'Red') return 'COLOR_RED';
    if (code === 404 || key === 'ColorF1Green' || key === 'Green') return 'COLOR_GREEN';
    if (code === 405 || key === 'ColorF2Yellow' || key === 'Yellow') return 'COLOR_YELLOW';
    if (code === 406 || key === 'ColorF3Blue' || key === 'Blue') return 'COLOR_BLUE';

    return null;
  }

  function shouldThrottleMovement() {
    var now = Date.now();
    var delta = now - state.lastMoveTimestamp;
    if (delta < CONSTANTS.THROTTLE_INTERVAL) {
      return true; // Discard event
    }
    if (delta < 120) {
      state.rapidCount++;
    } else {
      state.rapidCount = 0;
    }
    state.lastMoveTimestamp = now;
    return false;
  }

  // ---------------------------------------------------------------------------
  // 4. Candidate Validation & Navigability Filter
  // ---------------------------------------------------------------------------

  function isNavigable(element) {
    if (!element || element.nodeType !== 1) return false;
    if (element.getAttribute('data-nav') === 'false') return false;

    // Disabled or aria-disabled/aria-hidden exclusions
    if (element.disabled || element.hasAttribute('disabled')) return false;
    if (element.getAttribute('aria-disabled') === 'true') return false;
    if (element.getAttribute('aria-hidden') === 'true') return false;

    // Document tree containment
    if (typeof document !== 'undefined' && !document.body.contains(element)) {
      return false;
    }

    // Modal / trap scope check
    if (state.activeTrap) {
      if (!state.activeTrap.contains(element)) return false;
    } else {
      // Inactive view exclusion: elements inside an inactive .view are excluded
      var parentView = element.closest('.view');
      if (parentView && !parentView.classList.contains('active')) {
        return false;
      }
    }

    // Geometry validation
    var rect = element.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;

    // Computed style check
    if (typeof window !== 'undefined' && window.getComputedStyle) {
      var style = window.getComputedStyle(element);
      if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
        return false;
      }
    }

    return true;
  }

  function getCandidates(scopeElement) {
    var candidates = [];
    var rootScope = scopeElement || state.activeTrap;

    if (rootScope) {
      var found = rootScope.querySelectorAll(CONFIG.navigableSelector);
      for (var i = 0; i < found.length; i++) {
        if (isNavigable(found[i])) candidates.push(found[i]);
      }
      return candidates;
    }

    if (typeof document === 'undefined') return candidates;

    // 1. Persistent Header items (if header is not hidden)
    var header = document.querySelector(CONFIG.headerSelector);
    if (header && !header.classList.contains(CONFIG.headerHiddenClass)) {
      var headerItems = header.querySelectorAll(CONFIG.navigableSelector);
      for (var h = 0; h < headerItems.length; h++) {
        if (isNavigable(headerItems[h])) candidates.push(headerItems[h]);
      }
    }

    // 2. Active View items
    var activeView = document.querySelector(CONFIG.activeViewSelector);
    if (activeView) {
      var viewItems = activeView.querySelectorAll(CONFIG.navigableSelector);
      for (var v = 0; v < viewItems.length; v++) {
        if (isNavigable(viewItems[v])) candidates.push(viewItems[v]);
      }
    }

    return candidates;
  }

  // ---------------------------------------------------------------------------
  // 5. 2D Spatial Distance & Scoring Algorithm
  // ---------------------------------------------------------------------------

  function computeGeometricScore(currentRect, candRect, direction, coneTan) {
    var R = currentRect;
    var C = candRect;

    var Rcx = R.left + R.width / 2;
    var Rcy = R.top + R.height / 2;
    var Ccx = C.left + C.width / 2;
    var Ccy = C.top + C.height / 2;

    var eps = CONFIG.epsilon;
    var dPrimary = 0;
    var dOrthogonal = 0;
    var deltaPrimary = 0;
    var deltaOrthogonal = 0;
    var orthOverlap = 0;

    if (direction === 'right') {
      // Must be positioned forward in +X
      if (C.left < R.right - eps && Ccx <= Rcx) return { qualified: false };
      deltaPrimary = Ccx - Rcx;
      deltaOrthogonal = Math.abs(Ccy - Rcy);
      if (deltaPrimary <= 0) return { qualified: false };
      if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };

      dPrimary = (C.left >= R.right) ? (C.left - R.right) : Math.max(0, deltaPrimary * 0.5);
      orthOverlap = Math.max(0, Math.min(R.bottom, C.bottom) - Math.max(R.top, C.top));
      if (orthOverlap > 0) {
        dOrthogonal = deltaOrthogonal * 0.5;
      } else {
        var gapY = (C.top > R.bottom) ? (C.top - R.bottom) : (R.top - C.bottom);
        dOrthogonal = gapY + deltaOrthogonal * 0.5;
      }
    } else if (direction === 'left') {
      // Must be positioned forward in -X
      if (C.right > R.left + eps && Ccx >= Rcx) return { qualified: false };
      deltaPrimary = Rcx - Ccx;
      deltaOrthogonal = Math.abs(Ccy - Rcy);
      if (deltaPrimary <= 0) return { qualified: false };
      if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };

      dPrimary = (R.left >= C.right) ? (R.left - C.right) : Math.max(0, deltaPrimary * 0.5);
      orthOverlap = Math.max(0, Math.min(R.bottom, C.bottom) - Math.max(R.top, C.top));
      if (orthOverlap > 0) {
        dOrthogonal = deltaOrthogonal * 0.5;
      } else {
        var gapY = (C.top > R.bottom) ? (C.top - R.bottom) : (R.top - C.bottom);
        dOrthogonal = gapY + deltaOrthogonal * 0.5;
      }
    } else if (direction === 'down') {
      // Must be positioned forward in +Y
      if (C.top < R.bottom - eps && Ccy <= Rcy) return { qualified: false };
      deltaPrimary = Ccy - Rcy;
      deltaOrthogonal = Math.abs(Ccx - Rcx);
      if (deltaPrimary <= 0) return { qualified: false };
      if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };

      dPrimary = (C.top >= R.bottom) ? (C.top - R.bottom) : Math.max(0, deltaPrimary * 0.5);
      orthOverlap = Math.max(0, Math.min(R.right, C.right) - Math.max(R.left, C.left));
      if (orthOverlap > 0) {
        dOrthogonal = deltaOrthogonal * 0.5;
      } else {
        var gapX = (C.left > R.right) ? (C.left - R.right) : (R.left - C.right);
        dOrthogonal = gapX + deltaOrthogonal * 0.5;
      }
    } else if (direction === 'up') {
      // Must be positioned forward in -Y
      if (C.bottom > R.top + eps && Ccy >= Rcy) return { qualified: false };
      deltaPrimary = Rcy - Ccy;
      deltaOrthogonal = Math.abs(Ccx - Rcx);
      if (deltaPrimary <= 0) return { qualified: false };
      if (coneTan && deltaOrthogonal > deltaPrimary * coneTan) return { qualified: false };

      dPrimary = (R.top >= C.bottom) ? (R.top - C.bottom) : Math.max(0, deltaPrimary * 0.5);
      orthOverlap = Math.max(0, Math.min(R.right, C.right) - Math.max(R.left, C.left));
      if (orthOverlap > 0) {
        dOrthogonal = deltaOrthogonal * 0.5;
      } else {
        var gapX = (C.left > R.right) ? (C.left - R.right) : (R.left - C.right);
        dOrthogonal = gapX + deltaOrthogonal * 0.5;
      }
    } else {
      return { qualified: false };
    }

    var overlapBonus = Math.min(orthOverlap, CONFIG.maxOverlapBonus) * CONFIG.overlapWeight;
    var totalScore = dPrimary + (CONFIG.orthogonalWeight * dOrthogonal) - overlapBonus;
    var euclideanDist = Math.sqrt(deltaPrimary * deltaPrimary + deltaOrthogonal * deltaOrthogonal);

    return {
      qualified: true,
      score: totalScore,
      overlap: orthOverlap,
      euclidean: euclideanDist,
      dPrimary: dPrimary,
      dOrthogonal: dOrthogonal
    };
  }

  function findBestCandidate(currentElement, direction, candidates) {
    var dir = normalizeDirection(direction);
    if (!dir || !currentElement) return null;

    var currentRect = currentElement.getBoundingClientRect();
    var list = candidates || getCandidates();
    if (!list || !list.length) return null;

    var strictTan = Math.tan((CONFIG.strictConeAngle * Math.PI) / 180);   // ~1.732 for 60 deg
    var fallbackTan = Math.tan((CONFIG.fallbackConeAngle * Math.PI) / 180); // ~11.43 for 85 deg

    // Pass 1: Strict Angle Cone (60 degrees)
    var best = null;
    var bestRes = null;

    for (var i = 0; i < list.length; i++) {
      var cand = list[i];
      if (cand === currentElement) continue;

      var candRect = cand.getBoundingClientRect();
      if (candRect.width <= 0 || candRect.height <= 0) continue;

      var res = computeGeometricScore(currentRect, candRect, dir, strictTan);
      if (res.qualified) {
        if (!bestRes || res.score < bestRes.score) {
          best = cand;
          bestRes = res;
        } else if (Math.abs(res.score - bestRes.score) < 1.0) {
          // Tie-breaking: Tier 1 Overlap -> Tier 2 Euclidean -> Tier 3 DOM Order
          if (res.overlap > bestRes.overlap) {
            best = cand;
            bestRes = res;
          } else if (res.overlap === bestRes.overlap) {
            if (res.euclidean < bestRes.euclidean) {
              best = cand;
              bestRes = res;
            } else if (res.euclidean === bestRes.euclidean) {
              if (currentElement.compareDocumentPosition &&
                  (best.compareDocumentPosition(cand) & Node.DOCUMENT_POSITION_PRECEDING)) {
                best = cand;
                bestRes = res;
              }
            }
          }
        }
      }
    }

    if (best) return best;

    // Pass 2: Fallback Cone (85 degrees)
    for (var j = 0; j < list.length; j++) {
      var cand2 = list[j];
      if (cand2 === currentElement) continue;

      var candRect2 = cand2.getBoundingClientRect();
      if (candRect2.width <= 0 || candRect2.height <= 0) continue;

      var res2 = computeGeometricScore(currentRect2, candRect2, dir, fallbackTan);
      if (res2.qualified) {
        if (!bestRes || res2.score < bestRes.score) {
          best = cand2;
          bestRes = res2;
        } else if (Math.abs(res2.score - bestRes.score) < 1.0) {
          if (res2.overlap > bestRes.overlap) {
            best = cand2;
            bestRes = res2;
          } else if (res2.overlap === bestRes.overlap && res2.euclidean < bestRes.euclidean) {
            best = cand2;
            bestRes = res2;
          }
        }
      }
    }

    return best;
  }

  // ---------------------------------------------------------------------------
  // 6. Two-Tier TV-Safe Auto-Scroll Subsystem
  // ---------------------------------------------------------------------------

  function autoScrollShelf(element) {
    if (!element) return;
    var rail = element.closest('.shelf-rail, .cards-carousel, [data-scroll-rail="true"]');
    if (!rail) return;

    var behavior = state.rapidCount > 2 ? 'auto' : 'smooth';

    // Case 1: First element reset
    if (!element.previousElementSibling || element.getAttribute('data-nav-index') === '0') {
      if (rail.scrollLeft !== 0) {
        rail.scrollTo({ left: 0, behavior: behavior });
      }
      return;
    }

    var rect = element.getBoundingClientRect();
    var current = rail.scrollLeft || 0;

    // Case 2: Clipped on Left (< 96px)
    if (rect.left < CONSTANTS.SAFE_X_MIN) {
      var dLeft = CONSTANTS.SAFE_X_MIN - rect.left;
      rail.scrollTo({ left: Math.max(0, current - dLeft), behavior: behavior });
      return;
    }

    // Case 3: Clipped on Right (> 1824px)
    if (rect.right > CONSTANTS.SAFE_X_MAX) {
      var dRight = rect.right - CONSTANTS.SAFE_X_MAX;
      var targetRight = current + dRight + CONSTANTS.PEEK_OFFSET;
      if (rail.scrollWidth > rail.clientWidth && rail.clientWidth > 0) {
        targetRight = Math.min(rail.scrollWidth - rail.clientWidth, targetRight);
      }
      rail.scrollTo({ left: targetRight, behavior: behavior });
      return;
    }
  }

  function autoScrollViewport(element) {
    if (!element) return;

    // Header items reset viewport to top
    if (element.closest(CONFIG.headerSelector)) {
      var activePane = document.querySelector(CONFIG.activeViewSelector + ' .view-scroll-pane');
      if (activePane && activePane.scrollTop !== 0) {
        activePane.scrollTo({ top: 0, behavior: 'smooth' });
      }
      return;
    }

    var pane = element.closest('.view-scroll-pane');
    if (!pane) return;

    var behavior = state.rapidCount > 2 ? 'auto' : 'smooth';

    // Hero banner items reset viewport to top
    if (element.closest('.hero-banner')) {
      if (pane.scrollTop !== 0) {
        pane.scrollTo({ top: 0, behavior: behavior });
      }
      return;
    }

    var currentY = pane.scrollTop || 0;
    var shelf = element.closest('.content-shelf');

    if (shelf) {
      var shelfRect = shelf.getBoundingClientRect();
      var cardRect = element.getBoundingClientRect();

      // Sub-case 3a: Shelf header occluded by fixed header (< 104px)
      if (shelfRect.top < CONSTANTS.EFFECTIVE_Y_MIN) {
        var dUp = CONSTANTS.EFFECTIVE_Y_MIN - shelfRect.top;
        pane.scrollTo({ top: Math.max(0, currentY - dUp), behavior: behavior });
        return;
      }

      // Sub-case 3b: Card bottom clipped past TV safe boundary (> 1026px)
      if (cardRect.bottom > CONSTANTS.SAFE_Y_MAX) {
        var dDown = cardRect.bottom - CONSTANTS.SAFE_Y_MAX;
        pane.scrollTo({ top: currentY + dDown + 36, behavior: behavior });
        return;
      }
      return;
    }

    // Generic grid or list item
    var itemRect = element.getBoundingClientRect();
    if (itemRect.top < CONSTANTS.EFFECTIVE_Y_MIN) {
      var diffTop = CONSTANTS.EFFECTIVE_Y_MIN - itemRect.top;
      pane.scrollTo({ top: Math.max(0, currentY - diffTop - 24), behavior: behavior });
    } else if (itemRect.bottom > CONSTANTS.SAFE_Y_MAX) {
      var diffBottom = itemRect.bottom - CONSTANTS.SAFE_Y_MAX;
      pane.scrollTo({ top: currentY + diffBottom + 36, behavior: behavior });
    }
  }

  function autoScroll(element) {
    if (!element) return;
    // In headless / Node / JSDOM test environments, execute synchronously
    var isHeadless = typeof window !== 'undefined' && (
      !window.requestAnimationFrame ||
      (window.navigator && /jsdom/i.test(window.navigator.userAgent)) ||
      window.__TEST_M3__
    );

    if (isHeadless) {
      autoScrollShelf(element);
      autoScrollViewport(element);
    } else if (typeof window !== 'undefined' && window.requestAnimationFrame) {
      window.requestAnimationFrame(function () {
        autoScrollShelf(element);
        autoScrollViewport(element);
      });
    } else {
      autoScrollShelf(element);
      autoScrollViewport(element);
    }
  }

  // ---------------------------------------------------------------------------
  // 7. Focus Management & Focus Memory
  // ---------------------------------------------------------------------------

  function setFocus(element, options) {
    if (!element || !isNavigable(element)) return false;

    var opts = options || {};
    var prev = state.currentFocus;

    // Remove focus styling from previous element
    if (prev && prev !== element) {
      prev.classList.remove(CONFIG.activeClass, CONFIG.tvFocusedClass);
      emit('blur', { element: prev, nextElement: element });
    }

    // Sanitize any stray focused elements in DOM for robustness
    if (typeof document !== 'undefined') {
      var strays = document.querySelectorAll('.' + CONFIG.activeClass);
      for (var s = 0; s < strays.length; s++) {
        if (strays[s] !== element) {
          strays[s].classList.remove(CONFIG.activeClass, CONFIG.tvFocusedClass);
        }
      }
    }

    state.previousFocus = prev;
    state.currentFocus = element;

    element.classList.add(CONFIG.activeClass, CONFIG.tvFocusedClass);

    if (typeof element.focus === 'function') {
      try {
        element.focus({ preventScroll: opts.preventScroll !== false });
      } catch (_) {}
    }

    // Execute Two-Tier Auto-Scroll
    autoScroll(element);

    if (!opts.silent) {
      emit('focus', {
        element: element,
        previousElement: prev,
        previous: prev,
        view: getCurrentViewName()
      });
    }

    return true;
  }

  function saveFocus(viewName) {
    var vName = viewName || getCurrentViewName();
    var current = state.currentFocus;
    if (!current || !document.body.contains(current)) return;

    var viewEl = document.getElementById('view-' + vName);
    var isInsideHeader = current.closest && current.closest(CONFIG.headerSelector);

    // If currently on header, preserve existing content memory if available
    if (isInsideHeader && state.viewMemory[vName] && !state.viewMemory[vName].isHeader) {
      return;
    }

    state.viewMemory[vName] = {
      element: current,
      id: current.id || null,
      group: current.getAttribute('data-nav-group') || null,
      index: current.getAttribute('data-nav-index') ? parseInt(current.getAttribute('data-nav-index'), 10) : null,
      title: current.getAttribute('data-title') || null,
      isHeader: !!isInsideHeader,
      timestamp: Date.now()
    };
  }

  function restoreFocus(viewName, fallbackSelector) {
    var vName = viewName || getCurrentViewName();
    var mem = state.viewMemory[vName];
    var viewEl = document.getElementById('view-' + vName);
    var candidate = null;
    var resolutionMethod = 'none';

    // 1. Direct Node Reference
    if (mem && mem.element && document.body.contains(mem.element) && isNavigable(mem.element)) {
      candidate = mem.element;
      resolutionMethod = 'memory-node';
    }

    // 2. Element ID
    if (!candidate && mem && mem.id) {
      var byId = document.getElementById(mem.id);
      if (byId && isNavigable(byId)) {
        candidate = byId;
        resolutionMethod = 'memory-id';
      }
    }

    // 3. Group + Index
    if (!candidate && mem && mem.group && viewEl) {
      if (mem.index !== null && mem.index !== undefined) {
        var byGroupIdx = viewEl.querySelector('[data-nav-group="' + mem.group + '"][data-nav-index="' + mem.index + '"]');
        if (byGroupIdx && isNavigable(byGroupIdx)) {
          candidate = byGroupIdx;
          resolutionMethod = 'memory-group-index';
        }
      }
      if (!candidate && mem.title) {
        var byGroupTitle = viewEl.querySelector('[data-nav-group="' + mem.group + '"][data-title="' + mem.title + '"]');
        if (byGroupTitle && isNavigable(byGroupTitle)) {
          candidate = byGroupTitle;
          resolutionMethod = 'memory-group-title';
        }
      }
    }

    // 4. Custom Fallback Selector
    if (!candidate && fallbackSelector) {
      var byFallback = viewEl ? viewEl.querySelector(fallbackSelector) : document.querySelector(fallbackSelector);
      if (byFallback && isNavigable(byFallback)) {
        candidate = byFallback;
        resolutionMethod = 'fallback-custom';
      }
    }

    // 5. View Default Attribute
    if (!candidate && viewEl) {
      var byDefault = viewEl.querySelector('[data-nav-default="true"]');
      if (byDefault && isNavigable(byDefault)) {
        candidate = byDefault;
        resolutionMethod = 'view-default';
      }
      if (!candidate) {
        var byActiveFilter = viewEl.querySelector('.filter-pill.active[data-nav="true"]');
        if (byActiveFilter && isNavigable(byActiveFilter)) {
          candidate = byActiveFilter;
          resolutionMethod = 'view-active-filter';
        }
      }
    }

    // 6. First Navigable in View
    if (!candidate && viewEl) {
      var firstNav = viewEl.querySelector(CONFIG.navigableSelector);
      if (firstNav && isNavigable(firstNav)) {
        candidate = firstNav;
        resolutionMethod = 'view-first';
      }
    }

    // Fallback: Active Header Pill
    if (!candidate) {
      var headerPill = document.querySelector('.app-header .nav-pill-item.active[data-nav="true"]') ||
                       document.querySelector('.app-header [data-nav="true"]');
      if (headerPill && isNavigable(headerPill)) {
        candidate = headerPill;
        resolutionMethod = 'header-fallback';
      }
    }

    if (candidate) {
      setFocus(candidate);
      emit('viewrestore', { view: vName, element: candidate, method: resolutionMethod });
    }

    return candidate;
  }

  // ---------------------------------------------------------------------------
  // 8. Directional Movement & Keydown Dispatcher
  // ---------------------------------------------------------------------------

  function move(direction, event) {
    if (!state.enabled) return null;

    var current = state.currentFocus;

    // Self-healing: if current focus is detached or null, recover
    if (!current || !document.body.contains(current)) {
      var recovered = restoreFocus(getCurrentViewName());
      if (recovered) {
        state.currentFocus = recovered;
        current = recovered;
      } else {
        return null;
      }
    }

    var best = findBestCandidate(current, direction);
    if (best) {
      if (event && typeof event.preventDefault === 'function') {
        event.preventDefault();
      }
      setFocus(best);
      emit('navigate', { direction: direction, fromElement: current, toElement: best });
      return best;
    } else {
      emit('deadend', { direction: direction, element: current, currentElement: current });
      return null;
    }
  }

  function handleKeyDown(e) {
    if (!state.enabled || !e) return;
    var action = resolveKeyAction(e);
    if (!action) return;

    // 1. Directional Movements
    if (action.indexOf('MOVE_') === 0) {
      if (shouldThrottleMovement()) {
        if (typeof e.preventDefault === 'function') e.preventDefault();
        return;
      }

      if (typeof e.preventDefault === 'function') e.preventDefault();

      var dirMap = {
        MOVE_UP: 'up',
        MOVE_DOWN: 'down',
        MOVE_LEFT: 'left',
        MOVE_RIGHT: 'right'
      };
      var direction = dirMap[action];
      var moved = move(direction, e);
      if (!moved) {
        emit('deadend', { direction: direction, element: state.currentFocus, currentElement: state.currentFocus });
      }
      return;
    }

    state.rapidCount = 0;

    // 2. Select / Confirmation (Enter/OK Key)
    if (action === 'SELECT') {
      if (typeof e.preventDefault === 'function') e.preventDefault();
      var cur = state.currentFocus;
      if (cur) {
        emit('select', { element: cur });
        cur.click();
      }
      return;
    }

    // 3. Back Navigation
    if (action === 'BACK') {
      if (typeof e.preventDefault === 'function') e.preventDefault();
      handleBackNavigation();
      return;
    }

    // 4. Media Playback Controls
    if (action.indexOf('MEDIA_') === 0) {
      if (typeof e.preventDefault === 'function') e.preventDefault();
      emit('mediakey', {
        action: action,
        keyCode: e.keyCode || e.which,
        originalEvent: e
      });
      return;
    }

    // 5. Dedicated Color Keys
    if (action.indexOf('COLOR_') === 0) {
      if (typeof e.preventDefault === 'function') e.preventDefault();
      var color = action.replace('COLOR_', '').toLowerCase();
      emit('colorkey', {
        color: color,
        keyCode: e.keyCode || e.which,
        originalEvent: e
      });
      return;
    }
  }

  function handleBackNavigation() {
    var handled = false;
    var listeners = state.listeners['back'];
    if (listeners && listeners.length) {
      for (var i = 0; i < listeners.length; i++) {
        var res = listeners[i]();
        if (res === true) handled = true;
      }
    }
    if (!handled && typeof root.CinejoyApp !== 'undefined' && root.CinejoyApp.handleBackNavigation) {
      root.CinejoyApp.handleBackNavigation();
    }
  }

  // ---------------------------------------------------------------------------
  // 9. Public SpatialNav Module API
  // ---------------------------------------------------------------------------

  var SpatialNav = {
    KEY_CODES: KEY_CODES,
    CONSTANTS: CONSTANTS,

    init: function (options) {
      if (state.initialized) {
        if (options) {
          if (typeof options.onBack === 'function') this.on('back', options.onBack);
          if (typeof options.onSelect === 'function') this.on('select', options.onSelect);
          if (typeof options.onMediaKey === 'function') this.on('mediakey', options.onMediaKey);
          if (typeof options.onColorKey === 'function') this.on('colorkey', options.onColorKey);
        }
        return;
      }
      state.initialized = true;
      state.enabled = true;

      if (options) {
        for (var k in options) {
          if (options.hasOwnProperty(k) && CONFIG.hasOwnProperty(k)) {
            CONFIG[k] = options[k];
          }
        }
        if (typeof options.onBack === 'function') this.on('back', options.onBack);
        if (typeof options.onSelect === 'function') this.on('select', options.onSelect);
        if (typeof options.onMediaKey === 'function') this.on('mediakey', options.onMediaKey);
        if (typeof options.onColorKey === 'function') this.on('colorkey', options.onColorKey);
      }

      var self = this;
      state._keydownHandler = function (e) {
