      state.initialized = false;
      state.enabled = true;

      if (state._keydownHandler && typeof window !== 'undefined' && window.removeEventListener) {
        window.removeEventListener('keydown', state._keydownHandler);
        state._keydownHandler = null;
      }
    },

    enable: function () { state.enabled = true; },
    disable: function () { state.enabled = false; },
    isEnabled: function () { return state.enabled; },

    move: move,
    setFocus: setFocus,
    getCurrentFocus: function () {
      if (state.currentFocus && typeof document !== 'undefined' && !document.body.contains(state.currentFocus)) {
        state.currentFocus = null;
      }
      return state.currentFocus;
    },
    clearFocus: function () {
      if (state.currentFocus) {
        state.currentFocus.classList.remove(CONFIG.activeClass, CONFIG.tvFocusedClass);
        state.currentFocus = null;
      }
    },

    saveFocus: saveFocus,
    restoreFocus: restoreFocus,
    resetFocus: function (vName) {
      if (vName) {
        delete state.viewMemory[vName];
      } else {
        state.viewMemory = {};
      }
    },
    clearMemory: function (vName) {
      if (vName) {
        delete state.viewMemory[vName];
      } else {
        state.viewMemory = {};
      }
    },
    clearAllMemory: function () { state.viewMemory = {}; },

    trap: function (container) {
