args.ReplacementContent:
/**
 * Handle remote control and keyboard navigation
 */
handleKeyDown: function (e) {
  // If SpatialNav is enabled on the window, it manages all remote key events
  if (typeof window !== 'undefined' && window.SpatialNav && window.SpatialNav.isEnabled && window.SpatialNav.isEnabled()) {
    return;
  }

  var key = e.key;
  var keyCode = e.keyCode;

  // webOS Back Key (keycode 461), Escape (27), Backspace
  if (keyCode === 461 || key === 'Escape') {
    e.preventDefault();
    this.handleBackNavigation();
    return;
  }

  // Enter / OK key (keycode 13)
  if (key === 'Enter' || keyCode === 13) {
    if (this.state.focusedElement) {
      this.state.focusedElement.click();
    }
    return;
  }

  // Spatial Arrow keys
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(key) !== -1) {
    this.navigateSpatial(key, e);
  }
},

/**
 * Back button hierarchical handler
 */
handleBackNavigation: function () {
  if (this.state.currentView === 'player') {
    this.exitPlayer();
  } else if (this.state.currentView === 'details') {
    var returnView = this.state.detailsOriginView || this.state.previousView || 'home';
    if (returnView === 'details' || returnView === 'player') returnView = 'home';
    this.state.detailsOriginView = null;
    this.switchView(returnView);
  } else if (this.state.currentView !== 'home') {
    this.switchView('home');
  } else {
    console.log('[CinejoyApp] Back pressed on home view. (webOS app exit threshold)');
  }
},

/**
 * Handle remote control media keys
 */
handleMediaKey: function (action) {
  var video = document.getElementById('main-video-player');
  if (!video) return;

  switch (action) {
    case 'MEDIA_PLAY':
      try { video.play(); } catch (_) {}
      break;
    case 'MEDIA_PAUSE':
      try { video.pause(); } catch (_) {}
      break;
    case 'MEDIA_PLAY_PAUSE':
      try {
        if (video.paused) video.play();
        else video.pause();
      } catch (_) {}
      break;
    case 'MEDIA_STOP':
      try { video.pause(); } catch (_) {}
      this.exitPlayer();
      break;
    case 'MEDIA_FAST_FORWARD':
      try { video.currentTime = Math.min(video.duration || Infinity, video.currentTime + 10); } catch (_) {}
      break;
    case 'MEDIA_REWIND':
      try { video.currentTime = Math.max(0, video.currentTime - 10); } catch (_) {}
      break;
  }
},

/**
 * Handle remote control color keys
 */
handleColorKey: function (color) {
  if (this.state.currentView === 'search') {
    if (color === 'red') {
      this.state.searchQuery = '';
      var inputDisplay = document.getElementById('search-query-text');
      var placeholder = document.getElementById('search-query-placeholder');
      if (inputDisplay) inputDisplay.textContent = '';
      if (placeholder) placeholder.style.display = 'inline';
      this.updateSearchResults('');
    } else if (color === 'green') {
      this.state.searchQuery += ' ';
      var inputDisplay2 = document.getElementById('search-query-text');
      var placeholder2 = document.getElementById('search-query-placeholder');
      if (inputDisplay2) inputDisplay2.textContent = this.state.searchQuery;
      if (placeholder2) placeholder2.style.display = 'none';
      this.updateSearchResults(this.state.searchQuery);
    } else if (color === 'yellow' || color === 'blue') {
      var firstResult = document.querySelector('#search-results-grid [data-nav="true"]');
      if (firstResult) {
        this.setFocus(firstResult);
      } else if (color === 'blue') {
        this.switchView('home');
      }
    }
  } else if (this.state.currentView === 'player') {
    if (color === 'red') {
      var subBtn = document.getElementById('osd-subtitles-btn');
      if (subBtn) subBtn.click();
    } else if (color === 'green') {
      var srvBtn = document.getElementById('osd-server-btn');
      if (srvBtn) srvBtn.click();
    } else if (color === 'blue') {
      this.exitPlayer();
    }
  } else {
    if (color === 'red') this.switchView('search');
    else if (color === 'green') this.switchView('movies');
    else if (color === 'yellow') this.switchView('series');
    else if (color === 'blue') this.switchView('home');
  }
},

/**
 * Spatial 2D navigation algorithm between navigable items
 */
navigateSpatial: function (direction, event) {
  if (typeof window !== 'undefined' && window.SpatialNav) {
    var moved = window.SpatialNav.move(direction, event);
    if (moved) {
      this.state.focusedElement = moved;
    }
    return;
