#!/usr/bin/env node
/**
 * Cinejoy webOS - Milestone 3 Automated Test Suite
 * app/test-m3.js
 * 
 * Deterministic Verification Harness for Spatial Remote Navigation Engine:
 * - Suite 1: Test Environment & Layout Mock Harness (4 checks)
 * - Suite 2: Directional D-Pad Navigation (Cardinal Axes) (6 checks)
 * - Suite 3: Distance Weighting & Overlap Geometry Engine (5 checks)
 * - Suite 4: webOS Remote Keycodes & Remote Controls (7 checks)
 * - Suite 5: View Focus Memory & State Transitions (5 checks)
 * - Suite 6: TV Shelf & Viewport Auto-Scroll Calculations (5 checks)
 * - Suite 7: Edge Cases & Adversarial Robustness (6 checks)
 * 
 * Total: 38 Discrete Automated Checks
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// -----------------------------------------------------------------------------
// 1. Resolve JSDOM across available environments
// -----------------------------------------------------------------------------
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// -----------------------------------------------------------------------------
// 2. ANSI Terminal Colors & Reporting Infrastructure
// -----------------------------------------------------------------------------
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

function check(suiteId, testId, description, fn) {
  totalChecks++;
  const label = `[${suiteId}.${testId}] ${description}`;
  try {
    fn();
    passedChecks++;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.gray}Error: ${err.message}${C.reset}`);
  }
}

// -----------------------------------------------------------------------------
// 3. Layout and Scroll Mocks (1080p Canvas)
// -----------------------------------------------------------------------------

function installScrollMocks(window) {
  window.Element.prototype.scrollIntoView = function (options) {
    this._lastScrollIntoView = options || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };
}

function setupLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left,
      top: top,
      width: width,
      height: height,
      right: left + width,
      bottom: top + height,
      x: left,
      y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    // 1. Dynamic override via data-mock-rect attribute
    var mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        var parsed = JSON.parse(mockAttr);
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (err) {}
    }

    // 2. Elements with display: none or inside non-active views have zero geometry
    var view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style.display === 'none') {
      return makeRect(0, 0, 0, 0);
    }

    // 3. Known component mappings
    var id = this.id;
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
    if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
    if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
    if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);

    // Header brand & nav items
    if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList.contains('nav-pill-item')) {
      var route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Content Shelves
    if (this.classList.contains('content-shelf')) {
      var shelfIdx = Array.from(this.parentElement.children).indexOf(this);
      return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
    }

    // Poster cards
    if (this.classList.contains('card-poster')) {
      var parent = this.parentElement;
      var index = Array.from(parent.children).indexOf(this);
      var grid = this.closest('.content-grid-6col');
      if (grid) {
        var col = index % 6;
        var row = Math.floor(index / 6);
        return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
      }
      var isShelf1 = parent.closest('.content-shelf:nth-of-type(2)') || parent.closest('#shelf-trending');
      var top = isShelf1 ? 680 : 1060;
      return makeRect(96 + index * 244, top, 220, 330);
    }

    // Provider cards
    if (this.classList.contains('card-provider')) {
      var pIndex = Array.from(this.parentElement.children).indexOf(this);
      return makeRect(96 + pIndex * 184, 560, 160, 80);
    }

    // Episode cards
    if (this.classList.contains('card-episode')) {
      var epIndex = Array.from(this.parentElement.children).indexOf(this);
      return makeRect(96 + epIndex * 344, 670, 320, 180);
    }

    // Filter pills
    if (this.classList.contains('filter-pill')) {
      var fIndex = Array.from(this.parentElement.children).indexOf(this);
      return makeRect(96 + fIndex * 130, 110, 110, 44);
    }

    // Virtual keyboard keys
    if (this.classList.contains('key-btn')) {
      var rowEl = this.closest('.keyboard-row');
      var rIdx = rowEl ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
      var cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
      return makeRect(96 + cIdx * 60, 220 + rIdx * 60, 50, 50);
    }

    // Default fallback
    return makeRect(96, 100, 100, 40);
  };
}

// -----------------------------------------------------------------------------
// 4. Test Harness Creator & Key Dispatch Helper
// -----------------------------------------------------------------------------

function createTestHarness(initialRoute = 'home') {
  const htmlPath = path.resolve(__dirname, 'index.html');
  const configPath = path.resolve(__dirname, 'js/config.js');
  const navPath = path.resolve(__dirname, 'js/navigation.js');
  const appPath = path.resolve(__dirname, 'js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  window.__TEST_M3__ = true;
  installScrollMocks(window);
  setupLayoutMock(window);

  const configCode = fs.readFileSync(configPath, 'utf8');
  const navCode = fs.readFileSync(navPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(navCode);
  window.eval(appCode);

  window.CinejoyApp.init();

  return { dom, window, app: window.CinejoyApp, nav: window.SpatialNav };
}

function sendKey(window, key, keyCode) {
  const event = new window.KeyboardEvent('keydown', {
    key: key,
    keyCode: keyCode,
    which: keyCode,
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(event);
  return event;
}

// =============================================================================
// RUN SUITES
// =============================================================================

console.log(`${C.bold}${C.cyan}========================================================================${C.reset}`);
console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: MILESTONE 3 AUTOMATED VERIFICATION TEST HARNESS       ${C.reset}`);
console.log(`${C.bold}${C.cyan}   Spatial Remote Navigation Engine, Keycodes, Auto-Scroll & Memory     ${C.reset}`);
console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

// -----------------------------------------------------------------------------
// Suite 1: Test Environment & Layout Mock Harness (4 Checks)
// -----------------------------------------------------------------------------
console.log(`${C.bold}${C.magenta}▶ SUITE 1: Test Environment & Layout Mock Harness${C.reset}`);

check('S1', '1', '1920x1080 Full HD Viewport & Config Validation', () => {
  const { window } = createTestHarness();
  assert.strictEqual(window.CinejoyConfig.canvas.width, 1920, 'Canvas width must be 1920');
  assert.strictEqual(window.CinejoyConfig.canvas.height, 1080, 'Canvas height must be 1080');
  assert.strictEqual(window.CinejoyConfig.tvSafe.marginHorizontal, 96, 'TV safe X margin must be 96');
  assert.strictEqual(window.CinejoyConfig.tvSafe.marginVertical, 54, 'TV safe Y margin must be 54');
});

check('S1', '2', 'Mock getBoundingClientRect Layout Precision', () => {
  const { window } = createTestHarness();
  const playBtn = window.document.getElementById('hero-play-btn');
  const rect = playBtn.getBoundingClientRect();
  assert.strictEqual(rect.left, 96, 'Hero play btn left must be 96');
  assert.strictEqual(rect.top, 460, 'Hero play btn top must be 460');
  assert.strictEqual(rect.width, 180, 'Hero play btn width must be 180');
  assert.strictEqual(rect.height, 56, 'Hero play btn height must be 56');
});

check('S1', '3', 'Dynamic Sandbox Coordinate Override (data-mock-rect)', () => {
  const { window } = createTestHarness();
  const el = window.document.createElement('div');
  el.setAttribute('data-mock-rect', JSON.stringify({ left: 300, top: 400, width: 100, height: 50 }));
  window.document.body.appendChild(el);
  const r = el.getBoundingClientRect();
  assert.strictEqual(r.left, 300);
  assert.strictEqual(r.top, 400);
  assert.strictEqual(r.right, 400);
  assert.strictEqual(r.bottom, 450);
  assert.strictEqual(r.width, 100);
  assert.strictEqual(r.height, 50);
});

check('S1', '4', 'Scroll Container Mock Engine Tracking', () => {
  const { window } = createTestHarness();
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollTo({ left: 350, behavior: 'smooth' });
  assert.strictEqual(rail.scrollLeft, 350, 'scrollLeft must be recorded as 350');
  assert.strictEqual(rail._lastScrollBehavior, 'smooth', 'Scroll behavior must be smooth');
